#include "../overlay/src/helpers/esp32/V30Journal.h"
#include <assert.h>
#include <string.h>
#include <stdio.h>
using namespace v30;
struct MemoryStorage final:V30JournalStorage{V30JournalRecord records[kV30JournalMaxRecords]{};bool present[kV30JournalMaxRecords]{};size_t cap;bool failWrite=false;explicit MemoryStorage(size_t c=kV30JournalMaxRecords):cap(c){}size_t capacity()const override{return cap;}bool isEmpty(size_t i)const override{return i<cap&&!present[i];}bool read(size_t i,V30JournalRecord&o)override{if(i>=cap||!present[i])return false;o=records[i];return true;}bool write(size_t i,const V30JournalRecord&r)override{if(failWrite||i>=cap)return false;records[i]=r;present[i]=true;return true;}bool clear(size_t i)override{if(i>=cap)return false;present[i]=false;return true;}bool flush()override{return !failWrite;}void corrupt(size_t i){if(i<cap&&present[i])records[i].crc32^=1;}};
static V30JournalBundle bundle(uint8_t n,uint8_t peer=0xA0,JournalDirection d=JournalDirection::Outbound){V30JournalBundle b{};b.critical=1;b.direction=d;b.authenticated=1;memset(b.origin,n,32);memset(b.messageId,n+1,16);memset(b.peer,peer,32);b.payloadLen=3;b.payload[0]='v';b.payload[1]='3';b.payload[2]=n;return b;}
static V30JournalReceipt receiptFor(const V30JournalBundle&b,uint8_t sender){V30JournalReceipt r{};r.authenticated=1;memset(r.sender,sender,32);memcpy(r.recipient,b.origin,32);memcpy(r.origin,b.origin,32);memcpy(r.messageId,b.messageId,16);return r;}
static void rechecksum(V30JournalRecord&r){r.crc32=0;const auto*p=reinterpret_cast<const uint8_t*>(&r);uint32_t x=2166136261u;for(size_t i=0;i<sizeof(r);++i){x^=p[i];x*=16777619u;}r.crc32=x;}
int main(){MemoryStorage s;V30Journal j(s);assert(j.recover().validRecords==0);auto first=bundle(1);assert(j.admit(first)==JournalAdmission::Durable);assert(j.markTxAttempt(first));assert(j.markTxComplete(first));auto wrong=receiptFor(first,0xB0);assert(j.applyReceipt(wrong)==JournalReceiptResult::Rejected);auto good=receiptFor(first,0xA0);assert(j.applyReceipt(good)==JournalReceiptResult::Applied);assert(j.applyReceipt(good)==JournalReceiptResult::Duplicate);
 V30Journal reboot(s);assert(reboot.recover().validRecords>=1);assert(reboot.applyReceipt(good)==JournalReceiptResult::Duplicate);s.corrupt(3);V30Journal recovered(s);assert(recovered.recover().degraded);assert(recovered.applyReceipt(good)==JournalReceiptResult::Rejected);assert(recovered.receive(bundle(8,0xC0,JournalDirection::Inbound))==JournalAckAction::NoAck);
 auto inbound=bundle(9,0xC0,JournalDirection::Inbound);MemoryStorage receiveStorage(4);V30Journal rx(receiveStorage);assert(rx.receive(inbound)==JournalAckAction::AckAfterDurable);assert(rx.receive(inbound)==JournalAckAction::DuplicateAck);assert(!rx.markTxAttempt(inbound));auto invalid=inbound;invalid.payloadLen=129;assert(rx.receive(invalid)==JournalAckAction::NoAck);
 MemoryStorage fail(4);fail.failWrite=true;V30Journal noAck(fail);assert(noAck.receive(bundle(10,0xC0,JournalDirection::Inbound))==JournalAckAction::NoAck);
 MemoryStorage bounded(kV30JournalMaxRecords);V30Journal full(bounded);for(size_t i=0;i<kV30JournalMaxRecords;++i)assert(full.admit(bundle((uint8_t)i))==JournalAdmission::Durable);assert(full.admit(bundle(0xFE))==JournalAdmission::Durable);auto extra=bundle(0xFF);memset(extra.origin,0xEE,32);memset(extra.messageId,0xDD,16);assert(full.admit(extra)==JournalAdmission::Rejected);assert(!full.markTxAttempt(bundle(0)));V30Journal fullReboot(bounded);assert(fullReboot.recover().validRecords==kV30JournalMaxRecords);assert(fullReboot.admit(bundle(0))==JournalAdmission::Durable);
 MemoryStorage small(2);V30Journal limited(small);assert(limited.admit(bundle(20))==JournalAdmission::Durable);assert(limited.admit(bundle(21))==JournalAdmission::Durable);assert(limited.receive(bundle(22,0xA0,JournalDirection::Inbound))==JournalAckAction::NoAck);assert(!fullReboot.recover().degraded);
 MemoryStorage malformed(4);V30Journal seed(malformed);assert(seed.admit(bundle(30))==JournalAdmission::Durable);malformed.records[0].bundle.payloadLen=129;rechecksum(malformed.records[0]);V30Journal badLength(malformed);assert(badLength.recover().degraded);assert(badLength.admit(bundle(31))==JournalAdmission::Rejected);
 MemoryStorage overflow(4);V30Journal initial(overflow);assert(initial.admit(bundle(40))==JournalAdmission::Durable);overflow.records[0].generation=UINT32_MAX;rechecksum(overflow.records[0]);V30Journal exhausted(overflow);assert(exhausted.recover().degraded);assert(exhausted.admit(bundle(41))==JournalAdmission::Rejected);puts("v30 journal tests passed");return 0;}